//! The fold over the episode log. It mirrors the TypeScript kernel's `foldEpisode`
//! (`medha-core/src/episode.ts`), which is the reference: both engines open the same store, so the
//! same log must give the same state. `medha/src/__tests__/rust-parity.test.ts` checks that.
//!
//! Known gaps, not generated by that test yet: per-kind specs (thresholds, recency, signal-value
//! weighting, signal limits) are not applied here (medha-50q.7), and the decision tree is kept on
//! the state rather than folded from the log (medha-50q.10).

use crate::types::{EntityState, Episode, EpisodePayload};
use medha_core::decision::DecisionCase;
use medha_core::drift::ema_step;
use medha_core::formula::{compute_trust_and_status, TrustComputationInput};
use medha_core::thresholds::{DEFAULT_EMA_ALPHA, DEFAULT_THETA0, WEEK_MS};
use medha_core::types::{
    Anchor, EmaState, EntityKey, Evidence, GuardState, LifecycleStatus, RecencyConfig, Thresholds,
};
use std::collections::{HashMap, HashSet};

/// A fresh entity with no creation time; prefer [`fresh_state_at`] when the time is known.
pub fn fresh_state(key: EntityKey) -> EntityState {
    fresh_state_at(key, 0)
}

/// A fresh entity at `at`: probation, the default prior, no evidence.
pub fn fresh_state_at(key: EntityKey, at: i64) -> EntityState {
    EntityState {
        key,
        evidence: Evidence::default(),
        guard: GuardState::default(),
        anchors: Vec::new(),
        ema: EmaState {
            updated_at: at,
            ..EmaState::default()
        },
        status: LifecycleStatus::Probation,
        status_override: None,
        retired_at: None,
        restored_at: None,
        created_at: at,
        last_signal_at: None,
        updater: "ema".to_string(),
        last_note: None,
        authors: None,
        rejecting_authors: None,
        decision_tree: Vec::new(),
    }
}

/// `h`, the anchors durability counts: the distinct anchors, or the calendar-week fallback (one)
/// when there are none but the entity has a successful use (spec §4.4).
pub fn durability_anchor_count(state: &EntityState) -> usize {
    let distinct: HashSet<(&str, &str)> = state
        .anchors
        .iter()
        .map(|a| (a.kind.as_str(), a.value.as_str()))
        .collect();
    if distinct.is_empty() && state.last_signal_at.is_some() {
        1
    } else {
        distinct.len()
    }
}

/// The status the state justifies at `now`, given the status it already carries (the fold's
/// status lag: the stored status is an input, so a retirement latches).
pub fn status_for(state: &EntityState, now: i64) -> LifecycleStatus {
    let thresholds = Thresholds::default();
    let recency_config = RecencyConfig::default();
    compute_trust_and_status(TrustComputationInput {
        evidence: &state.evidence,
        guard: &state.guard,
        distinct_anchor_count: durability_anchor_count(state),
        ema: &state.ema,
        last_signal_at: state.last_signal_at,
        now,
        stored_status: state.status,
        status_override: state.status_override,
        thresholds: &thresholds,
        recency_config: &recency_config,
        rejecting_authors: state.rejecting_authors.as_ref().map(Vec::len),
    })
    .map(|res| res.status)
    .unwrap_or(state.status)
}

fn add_anchor(anchors: &mut Vec<Anchor>, anchor: Anchor) {
    if !anchors.contains(&anchor) {
        anchors.push(anchor);
    }
}

/// A lifecycle override: retire, quarantine or restore. A restore clears the override and puts the
/// entity back on probation without re-deriving its status (the next episode or read does that).
fn apply_override(state: &mut EntityState, override_type: &str, at: i64) {
    match override_type {
        "retired" => {
            let already_retired =
                state.status == LifecycleStatus::Retired && state.retired_at.is_some();
            state.status = LifecycleStatus::Retired;
            state.status_override = Some(LifecycleStatus::Retired);
            // A second retirement keeps the original clock, so retention is never reset.
            if !already_retired {
                state.retired_at = Some(at);
                state.restored_at = None;
            }
        }
        "quarantined" => {
            state.status = LifecycleStatus::Quarantined;
            state.status_override = Some(LifecycleStatus::Quarantined);
        }
        "restore" => {
            state.status = LifecycleStatus::Probation;
            state.status_override = None;
            state.retired_at = None;
            state.restored_at = Some(at);
        }
        _ => {}
    }
}

/// Fold one episode into the prior state of its key. `None` means the key has no entity after
/// it: an episode that found no entity and may not create one, or a purge.
pub fn fold_episode_into_state(
    current: Option<EntityState>,
    episode: &Episode,
) -> Option<EntityState> {
    let at = episode.at;
    match &episode.payload {
        EpisodePayload::Signal {
            spec,
            anchors,
            ensure,
            note,
            weight,
            case_id,
            ..
        } => {
            // An unknown entity is created only when the writer asked for it (spec §5.2).
            let mut state = match current {
                Some(state) => state,
                None if *ensure => fresh_state_at(episode.key.clone(), at),
                None => return None,
            };

            if let Some(cid) = case_id {
                if let Some(branch) = state.decision_tree.iter_mut().find(|c| &c.id == cid) {
                    if spec.counts_as_success {
                        branch.evidence.k += 1.0;
                    }
                    if spec.counts_as_trial {
                        branch.evidence.n += 1.0;
                    }
                    if let Ok(new_mu) = ema_step(Some(branch.ema.mu), spec.value, DEFAULT_EMA_ALPHA)
                    {
                        branch.ema.mu = new_mu;
                    }
                }
            }

            if spec.counts_as_success {
                state.evidence.k += 1.0;
            }
            if spec.counts_as_trial {
                state.evidence.n += 1.0;
            }
            if spec.name == "REJECT_CONTEXT" {
                state.evidence.context_rejects += 1;
            }

            // A weight-updater's result is carried by the episode; otherwise the EMA step.
            state.ema.mu = match weight {
                Some(w) => *w,
                None => ema_step(Some(state.ema.mu), spec.value, DEFAULT_EMA_ALPHA)
                    .unwrap_or(state.ema.mu),
            };
            state.ema.updated_at = at;

            if spec.counts_as_success {
                match anchors {
                    Some(declared) if !declared.is_empty() => {
                        for anchor in declared {
                            add_anchor(&mut state.anchors, anchor.clone());
                        }
                    }
                    // No host anchor on a success: the calendar-week fallback (spec §5.4).
                    _ => {
                        let week = (at as f64 / WEEK_MS).floor() as i64;
                        add_anchor(&mut state.anchors, Anchor::new("week", week.to_string()));
                    }
                }
                state.last_signal_at = Some(at);
            }

            if note.is_some() {
                state.last_note = note.clone();
            }
            state.status = status_for(&state, at);
            Some(state)
        }
        EpisodePayload::Guard {
            ok,
            kind,
            ensure,
            note,
        } => {
            let mut state = match current {
                Some(state) => state,
                None if *ensure => fresh_state_at(episode.key.clone(), at),
                None => return None,
            };
            if let Some(k) = kind {
                state.guard.kind = k.clone();
            }
            state.guard.last_ok = Some(*ok);
            state.guard.last_ok_at = Some(at);
            if note.is_some() {
                state.last_note = note.clone();
            }
            state.status = status_for(&state, at);
            Some(state)
        }
        EpisodePayload::Override {
            override_type,
            reason,
        } => {
            let mut state = current?;
            apply_override(&mut state, override_type, at);
            state.last_note = Some(reason.clone());
            Some(state)
        }
        EpisodePayload::Proposal {
            theta0,
            anchor,
            description,
            note,
            ..
        } => {
            // A proposal only introduces an entity; it never resets one that exists.
            if current.is_some() {
                return current;
            }
            let mut state = fresh_state_at(episode.key.clone(), at);
            if let Some(t0) = theta0 {
                state.ema.theta0 = *t0;
                state.ema.mu = *t0;
            }
            if let Some(a) = anchor {
                state.anchors.push(a.clone());
            }
            state.last_note = note.clone().or_else(|| description.clone());
            Some(state)
        }
        EpisodePayload::Sweep { action, .. } => {
            let mut state = current?;
            match action.as_str() {
                "purge" => return None,
                "quarantine" => apply_override(&mut state, "quarantined", at),
                "retire" | "archive" => apply_override(&mut state, "retired", at),
                "restore" => apply_override(&mut state, "restore", at),
                _ => {}
            }
            Some(state)
        }
        EpisodePayload::Baseline { state: baseline } => {
            // The checkpoint reproduces the folded prefix; its status is re-derived at its clock.
            let mut state = baseline.clone();
            state.status = status_for(&state, at);
            Some(state)
        }
        EpisodePayload::Decision {
            case_id,
            parent_id,
            detach,
            condition,
            decision,
        } => {
            let mut state = current?;
            if let Some(branch) = state.decision_tree.iter_mut().find(|c| &c.id == case_id) {
                branch.condition = condition.clone();
                branch.decision = decision.clone();
                if *detach == Some(true) {
                    branch.parent_id = None;
                } else if parent_id.is_some() {
                    branch.parent_id = parent_id.clone();
                }
            } else {
                state.decision_tree.push(DecisionCase {
                    id: case_id.clone(),
                    parent_id: parent_id.clone(),
                    condition: condition.clone(),
                    decision: decision.clone(),
                    evidence: Evidence::default(),
                    ema: EmaState {
                        mu: DEFAULT_THETA0,
                        theta0: DEFAULT_THETA0,
                        updated_at: at,
                        sample_count: 0,
                    },
                });
            }
            Some(state)
        }
        // Retractions are applied by `fold_log`; definitions are never evidential.
        EpisodePayload::Retract { .. } | EpisodePayload::Define { .. } => current,
    }
}

/// Rebuild every entity state from a log, in seq order, with retracted episodes masked.
pub fn fold_log(episodes: &[Episode]) -> HashMap<String, EntityState> {
    let mut ordered: Vec<&Episode> = episodes.iter().collect();
    ordered.sort_by_key(|e| e.seq);

    let retracted: HashSet<u64> = ordered
        .iter()
        .filter_map(|e| match &e.payload {
            EpisodePayload::Retract { target_seq, .. } => Some(*target_seq),
            _ => None,
        })
        .collect();

    let mut projection: HashMap<String, EntityState> = HashMap::new();
    for ep in ordered {
        if retracted.contains(&ep.seq) {
            continue;
        }
        let key_str = ep.key.to_string_repr();
        let curr = projection.remove(&key_str);
        if let Some(next) = fold_episode_into_state(curr, ep) {
            projection.insert(key_str, next);
        }
    }

    projection
}
